const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,week='',view='overview',query='',region='',modalPacket=null,modalChannel='email';
const titles={overview:['The delivery picture.','A weekly view of the work behind every potential partnership.'],tenders:['Opportunity, with context.','Requirements, delivery hypotheses and the next question to resolve.'],partners:['The people behind delivery.','Professional profiles and company capabilities, with uncertainty kept visible.'],outreach:['Start a useful conversation.','An offer for each actor. Email and LinkedIn drafts, ready to review.'],content:['Ideas worth sharing.','Technology-led editorial, without naming a proposed deal or consortium.'],diagnostics:['Evidence, not guesswork.','Inspect execution records, investigate failures and see what is still outstanding.'],integrations:['Connected by design.','Repository-first for the demo. Distribution is deliberately out of scope.']};
function badge(state){let cls=/COMPLETED|VALIDATED|SUCCESS/.test(state)?'green':/HOLD|EXPIRED|UNRESOLVED|PENDING|FAILED|FAILURE|BLOCKED/.test(state)?'amber':'gray';return `<span class="pill ${cls}">${esc(state.replaceAll('_',' '))}</span>`}
function isoWeek(date){let x=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));let y=x.getUTCFullYear();return `${y}-W${String(Math.ceil((((x-new Date(Date.UTC(y,0,1)))/86400000)+1)/7)).padStart(2,'0')}`}
function weekRange(w){const [y,n]=w.split('-W').map(Number),d=new Date(Date.UTC(y,0,4));d.setUTCDate(d.getUTCDate()-(d.getUTCDay()||7)+1+(n-1)*7);const end=new Date(d);end.setUTCDate(end.getUTCDate()+6);return `${d.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})} – ${end.toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'})}`}
function weeks(){let now=new Date();let next=new Date(now);next.setUTCDate(next.getUTCDate()+7);return [...new Set([...data.runs.map(r=>r.week),isoWeek(now),isoWeek(next)])].sort().reverse()}
function runs(){return data.runs.filter(r=>r.week===week).sort((a,b)=>b.started_at.localeCompare(a.started_at))}
const contact=id=>data.contacts.find(c=>c.id===id), company=id=>data.partners.find(c=>c.id===id);
function url(v){try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:'#'}catch{return '#'}}
function sourceLink(v,label='Official / research source ↗'){return `<a href="${esc(url(v))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`}
function overview(){const rr=runs(),last=rr[0],c=last?.counts;return `<div class="stats"><div class="stat featured"><span class="label">EXECUTIONS THIS WEEK</span><strong>${rr.length}</strong><small>${rr.length?(last.kind==='FRESH_SEARCH_BASED_RESEARCH'?'Fresh search-based research':'Observed repository replay'):'No execution recorded'}</small></div><div class="stat"><span class="label">TENDER DOSSIERS</span><strong>${c?.tenders??'—'}</strong><small>${last?(last.kind==='FRESH_SEARCH_BASED_RESEARCH'?'Fresh notices + known-open rechecks':'Validated from cached research'):'Awaiting an execution'}</small></div><div class="stat"><span class="label">ACTOR / TENDER PACKETS</span><strong>${c?.actor_tender_packets??'—'}</strong><small>Email + LinkedIn with follow-ups</small></div><div class="stat"><span class="label">DISTRIBUTION CALLS</span><strong>${last?rr.reduce((n,r)=>n+(r.distribution_calls||0),0):'—'}</strong><small>PoC mode · all messages unsent</small></div></div><div class="section-head"><div><h2>Execution trail</h2><p>Actual steps, including cached inputs and skipped services.</p></div>${last?badge(last.status):badge('NOT_RUN')}</div>${last?`<div class="surface"><div class="run-header"><div><strong>${last.kind==='REPOSITORY_POC_REPLAY'?'Repository validation & draft replay':'Workflow execution'}</strong><small>${esc(new Date(last.started_at).toLocaleString())} · ${esc(last.trigger)}</small></div><span class="run-id">${esc(last.id)}</span></div><div class="pipeline">${last.stages.map((s,i)=>`<div class="stage"><span class="num">STEP ${String(i+1).padStart(2,'0')}</span><strong>${esc(s.name)}</strong>${badge(s.state)}<p>${esc(s.detail)}</p></div>`).join('')}</div></div>`:`<div class="surface empty"><h3>No run in ${esc(week)} yet.</h3>The weekly schedule is prepared. A future week is not a completed execution.<br>Tender dossiers and draft content remain available in the other views.</div>`}<div class="two-col"><div><div class="section-head"><h2>Questions before a bid</h2><span class="pill">RESEARCH SNAPSHOT</span></div><div class="surface rows">${data.tenders.slice(0,4).map(t=>`<div class="row"><div><strong>${esc(t.id)} · ${esc(t.title)}</strong><small>${esc(t.next_action)}</small></div><button data-tender="${t.id}">Open ↗</button></div>`).join('')}</div></div><div><div class="section-head"><h2>Cost & continuity</h2></div><div class="surface pad"><span class="hint">CLAY DATA CREDIT CEILING / EXECUTION</span><h2 style="font-size:34px;margin:12px 0">299 <span style="font-size:12px;color:#71806e">credits</span></h2><div class="progress-track"><div class="progress-fill" style="width:${last?Math.min(100,(last.clay_data_credits||0)/299*100):0}%"></div></div><p class="hint">${last?`${last.clay_data_credits} DATA credits used. ${esc(last.clay_basis||'See run evidence for cached versus new data.')}`:'No credit usage reported for this week.'}</p><p class="hint">Unknown-cost live calls stay blocked. Optional channel failures do not stop the demo.</p></div></div></div><div class="section-head"><h2>Week by week</h2><span class="hint">No synthetic history</span></div><div class="week-history">${weeks().map(w=>`<button data-week="${w}" class="${w===week?'selected':''}"><strong>${w}</strong><small>${weekRange(w)}</small><span>${data.runs.filter(r=>r.week===w).length} observed runs</span></button>`).join('')}</div>${rr.length>1?`<div class="section-head"><h2>Other runs this week</h2></div><div class="surface rows">${rr.slice(1).map(r=>`<div class="row"><span>${esc(r.id)}</span>${badge(r.status)}</div>`).join('')}</div>`:''}`}
function filters(){return `<div class="filters"><input id="search" type="search" placeholder="Search titles, companies or regions…" value="${esc(query)}" aria-label="Search records"><select id="region" aria-label="Filter region"><option value="">All regions</option>${[...new Set(data.tenders.map(t=>t.region))].map(r=>`<option ${r===region?'selected':''}>${esc(r)}</option>`).join('')}</select></div>`}
function filteredTenders(){return data.tenders.filter(t=>(!region||t.region===region)&&`${t.id} ${t.title} ${t.buyer} ${t.country}`.toLowerCase().includes(query.toLowerCase()))}
function tenderView(){const ts=filteredTenders();return filters()+`<p class="hint">${ts.length} dossiers · snapshot as of ${data.data_as_of}. Week selection applies to execution history, not the current dossier register.</p><div class="cards">${ts.map(t=>`<article class="tender-card"><div class="mini"><span>${t.id} / ${esc(t.country)}</span><span>${t.actor_ids.length} actors</span></div><h3>${esc(t.title)}</h3><p>${esc(t.buyer)}</p><p>${esc(t.evidence_grade)}</p><div>${badge(t.delivery_route)}</div><div class="bottom"><span class="hint">${t.deadline?'Closes '+esc(t.deadline):'Deadline unverified'}</span><button data-tender="${t.id}">View dossier ↗</button></div></article>`).join('')||'<p class="empty">No dossiers match this filter.</p>'}</div>`}
function partnerView(){const rows=data.partners.filter(c=>`${c.name} ${c.country} ${c.capability_summary}`.toLowerCase().includes(query.toLowerCase()));return `<div class="filters"><input id="search" type="search" aria-label="Search partners" placeholder="Search company, country or capability…" value="${esc(query)}"></div><div class="cards">${rows.map(c=>`<article class="tender-card partner-card"><div class="mini"><span>${esc(c.country)}</span><span>${c.actor_ids.length} named actors</span></div><h3>${esc(c.name)}</h3><p>${esc(c.domain)}</p><p>${esc(c.capability_summary.slice(0,210))}${c.capability_summary.length>210?'…':''}</p><div class="bottom"><span class="hint">Participation unconfirmed</span><button data-partner="${c.id}">Inspect ↗</button></div></article>`).join('')||'<p class="empty">No partners match this filter.</p>'}</div>`}
function outreachView(){let ps=data.outreach.filter(p=>{let c=contact(p.actor_id),t=data.tenders.find(t=>t.id===p.tender_id);return (!region||t.region===region)&&`${p.tender_id} ${c.name} ${company(c.company_id).name}`.toLowerCase().includes(query.toLowerCase())});return filters()+`<div class="surface table-wrap"><table><thead><tr><th>ACTOR</th><th>TENDER</th><th>DELIVERY OFFER</th><th>DRAFTS</th><th></th></tr></thead><tbody>${ps.map(p=>{const c=contact(p.actor_id);return `<tr><td><strong>${esc(c.name)}</strong><small>${esc(company(c.company_id).name)}</small></td><td>${esc(p.tender_id)}<small>${esc(p.state)}</small></td><td style="max-width:300px">${esc(p.technical_offer)}</td><td>Email + 4<small>LinkedIn + 4</small></td><td><button data-packet="${p.tender_id}|${p.actor_id}">Read drafts ↗</button></td></tr>`}).join('')||'<tr><td colspan="5">No draft packets match this filter.</td></tr>'}</tbody></table></div><p class="hint">Direct email addresses are withheld from the public demo. All copy is unsent. Duplicate appearances reflect different tender associations, not additional people.</p>`}
function markdown(text){return text.split('\n\n').map(p=>p.startsWith('# ')?`<h1>${esc(p.slice(2))}</h1>`:p.startsWith('## ')?`<h2>${esc(p.slice(3))}</h2>`:`<p>${esc(p.replace(/^\*|\*$/g,''))}</p>`).join('')}
function contentView(){return data.content.map(c=>`<div class="surface article"><div class="article-meta">TECHNOLOGY / UTILITY INTEGRATION · ${badge('DRAFT_ONLY')}</div>${markdown(c.body)}</div>`).join('')}
function integrationsView(){const cs=[['Repository','Demo SSOT','PREPARED','Canonical tender and partner files feed this dashboard. The public repository and an earlier Actions replay are verified. See Diagnostics for this run’s publication and research evidence.'],['Attio','Optional CRM mirror','PRESERVED','The existing integration remains intact. Private record identifiers and direct contacts are outside the public repo. Fresh research may append verified private CRM notes; repository-only replay does not.'],['Clay','Cached decision-maker data','CACHED','299 DATA-credit ceiling. Durable reservation guard retained. This demo runs from existing research and makes no billable requests.'],['Woodpecker','Email drafts','DRAFT_ONLY','Initial message plus four followups per actor/tender. Pushing and sending are intentionally outside the PoC.'],['HeyReach','LinkedIn drafts','TRIAL_EXPIRED','Trial expired, as reported. Scripts remain available; no subscription, MCP connectivity or sending is assumed.'],['Mentic + SurferSEO','Marketing adapters','NOT_CONNECTED','Documentation and input/output contracts retained. No paid media, content-generation calls or publishing required for the demo.']];return `<div class="integration">${cs.map(c=>`<article class="surface"><div class="section-head" style="margin:0"><h3>${c[0]}</h3>${badge(c[2])}</div><span class="hint">${c[1]}</span><p>${c[3]}</p></article>`).join('')}</div><div class="surface pad" style="margin-top:18px"><h3>The demonstration boundary</h3><p class="hint">A completed repository replay means input, identity and draft validation completed. It does not mean tenders were freshly scraped, contacts re-enriched, companies agreed, or messages delivered. Future runs appear only when execution records are committed and the dashboard projection is rebuilt.</p></div>`}
function render(){if(!data)return;view=location.hash.slice(1)||'overview';if(!titles[view])view='overview';$('#title').textContent=titles[view][0];$('#subtitle').textContent=titles[view][1];$('#page-label').textContent=view.toUpperCase();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+view));$('#week-dates').textContent=weekRange(week);$('#notice').textContent=`PoC mode · Research snapshot ${data.data_as_of} · No messages sent · ${view==='overview'?'Execution history filtered to '+week:'Current repository dossiers; weekly runs shown in Overview'}`;$('#view').innerHTML=({overview,tenders:tenderView,partners:partnerView,outreach:outreachView,content:contentView,integrations:integrationsView,diagnostics:diagnosticsView}[view])();bind()}
function bind(){const inp=$('#search');if(inp)inp.oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};const reg=$('#region');if(reg)reg.onchange=e=>{region=e.target.value;render()};document.querySelectorAll('[data-tender]').forEach(b=>b.onclick=()=>openTender(b.dataset.tender));document.querySelectorAll('[data-partner]').forEach(b=>b.onclick=()=>openPartner(b.dataset.partner));document.querySelectorAll('[data-packet]').forEach(b=>b.onclick=()=>openPacket(b.dataset.packet));document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{week=b.dataset.week;$('#week').value=week;render()});if($('#copy-blog'))$('#copy-blog').onclick=e=>copy(data.content[0].body,e.target);bindDiagnostics()}
function show(label,html){$('#detail-label').textContent=label;$('#detail-body').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();bind()}
function openTender(id){const t=data.tenders.find(t=>t.id===id),ps=data.pairs.filter(p=>t.pair_ids.includes(p.id));show(`${id} / TENDER DOSSIER`,`<h2>${esc(t.title)}</h2><p class="hint">${esc(t.buyer)} · ${esc(t.country)} · snapshot ${t.evidence_date}</p><div class="detail-grid"><div><small>STATUS / EVIDENCE</small>${esc(t.status)}<br>${esc(t.evidence_grade)}</div><div><small>DEADLINE / CAVEAT</small>${esc(t.deadline||'Unverified')}<br>${esc(t.deadline_caveat)}</div><div><small>SOFTWARE</small>${esc(t.technology['Software evidence'])}</div><div><small>HARDWARE</small>${esc(t.technology['Hardware evidence'])}</div></div><p class="hint">${(t.source_urls||[t.source_url]).map(u=>sourceLink(u)).join(' · ')}</p>${t.value?`<h3>Value and participation gates</h3><p>${esc(JSON.stringify(t.value))}</p><p>${esc(t.eligibility)}</p><p>${esc(t.payment_security)}</p><div class="rows">${(t.earlier_gates||[]).map(g=>`<div class="row"><span>${esc(g.type)} · ${esc(g.value)}</span>${badge(g.state)}</div>`).join('')}</div>`:''}<h3>Next qualification step</h3><p class="detail-offer">${esc(t.next_action)}</p>${ps.map(p=>`<h3>${esc(p.id)} · Proposed delivery team</h3><p class="hint">${esc(p.assessment)}</p><p class="detail-offer">${esc(p.pitch)}</p><div class="detail-grid">${p.company_ids.map((cid,i)=>`<div><small>${esc(company(cid).name)}</small>${esc(p.roles[i])}</div>`).join('')}</div><p class="hint"><b>Unresolved:</b> ${esc(p.gates)}</p>`).join('')||'<p class="hint">No delivery team qualified yet. Single E2E and consortium options remain open.</p>'}<h3>Actor-specific drafts</h3><div class="rows">${t.actor_ids.map(cid=>`<div class="row"><div><strong>${esc(contact(cid).name)}</strong><small>${esc(contact(cid).title)}</small></div><button data-packet="${t.id}|${cid}">Read drafts</button></div>`).join('')||'<p class="hint">No identified actors for this dossier yet.</p>'}</div>`)}
function openPartner(id){let c=company(id);show('PARTNER / '+c.name,`<h2>${esc(c.name)}</h2><p class="hint">${esc(c.country)} · ${sourceLink('https://'+c.domain,c.domain)}</p><p class="detail-offer">${esc(c.capability_summary)}</p><p class="hint">${esc(c.data_caveat)}</p><h3>Professional contacts</h3>${c.actor_ids.map(cid=>{let p=contact(cid);return `<div class="surface pad" style="margin-top:10px"><div class="actors"><span class="avatar">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${esc(p.name)}</strong><p class="hint">${esc(p.title)}</p></div></div><p class="hint">${esc(p.role_assessment)}</p>${sourceLink(p.profile_url,'Professional profile ↗')}<p class="hint">Willingness: unknown · Business email: withheld from public demo</p></div>`}).join('')||'<p class="hint">No decision-maker qualified yet.</p>'}`)}
function openPacket(key){const [tid,cid]=key.split('|');modalPacket=data.outreach.find(p=>p.tender_id===tid&&p.actor_id===cid);modalChannel='email';packetBody()}
function packetBody(){let p=modalPacket,c=contact(p.actor_id),seq=p[modalChannel];show(`${p.tender_id} / ${c.name}`,`<h2>${esc(c.name)} · ${esc(company(c.company_id).name)}</h2><p class="hint">${esc(c.title)} · Unsent draft</p><p class="detail-offer">${esc(p.technical_offer)}</p><div class="tab-buttons"><button id="email-tab" class="${modalChannel==='email'?'selected':''}">Email sequence</button><button id="li-tab" class="${modalChannel==='linkedin'?'selected':''}">LinkedIn sequence</button><button id="copy-sequence">Copy sequence</button></div>${seq.subject?`<h3>Subject</h3><p class="detail-copy">${esc(seq.subject)}</p>`:''}${seq.connection?`<h3>Connection request</h3><p class="detail-copy">${esc(seq.connection)}</p>`:''}<h3>${modalChannel==='email'?'Initial email':'After connection'}</h3><p class="detail-copy">${esc(seq.initial)}</p>${seq.followups.map((f,i)=>`<h3>Follow-up ${i+1}</h3><p class="detail-copy">${esc(f)}</p>`).join('')}<p class="hint">${esc(p.followup_timing)} No recipient address is included in this public projection.</p>`);$('#email-tab').onclick=()=>{modalChannel='email';packetBody()};$('#li-tab').onclick=()=>{modalChannel='linkedin';packetBody()};$('#copy-sequence').onclick=e=>copy([seq.subject||seq.connection,seq.initial,...seq.followups].join('\n\n'),e.target)}
async function copy(t,b){try{await navigator.clipboard.writeText(t);b.textContent='Copied ✓'}catch{b.textContent='Copy unavailable; select the text'}}
async function load(){try{let r;let source='GitHub main';try{if(new URLSearchParams(location.search).has('local'))throw Error('Local preview requested');r=await fetch('https://raw.githubusercontent.com/az2kxx/gtmtechweek/main/dist/data.json?v='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('GitHub unavailable');data=await r.json()}catch{source=new URLSearchParams(location.search).has('local')?'Local preview data':'Hosted fallback — GitHub refresh unavailable';r=await fetch('data.json?v='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('Data unavailable');data=await r.json()}window.projectionSource=source;if(!week)week=data.runs.map(r=>r.week).sort().at(-1)||isoWeek(new Date());$('#week').innerHTML=weeks().map(w=>`<option value="${w}" ${w===week?'selected':''}>${w} · ${data.runs.filter(r=>r.week===w).length?'observed':'not run'}</option>`).join('');$('#refresh-label').textContent=(source==='GitHub main'?'GitHub · ':'Fallback · ')+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('#freshness').textContent=source.toUpperCase()+' · PROJECTION '+new Date(data.generated_at).toLocaleDateString()+' · REFRESHES EVERY 30s';if(data.config.github_repository){$('#repo-link').hidden=false;$('#repo-link').href='https://github.com/'+data.config.github_repository;$('#repo-state').textContent=data.config.github_repository}render()}catch(e){$('#refresh-label').textContent='Refresh failed';if(!data)$('#view').innerHTML='<p class="empty error">The repository projection could not be loaded. Use Refresh to retry.</p>';else $('#notice').textContent='Refresh failed — displaying the last loaded projection.'}}
$('#week').onchange=e=>{week=e.target.value;render()};$('#refresh').onclick=load;$('#close-detail').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};window.addEventListener('hashchange',()=>{query='';region='';render()});load();setInterval(load,30000);

let selectedRunId='',actionsState=null;
function diagnosticRun(){return runs().find(r=>r.id===selectedRunId)||runs()[0]}
function diagnosticsView(){const rs=runs(),r=diagnosticRun(),ready=data.readiness||[],failures=data.runs.filter(r=>r.status==='FAILED');return `<div class="stats"><div class="stat featured"><span class="label">WEEKLY RECORDS</span><strong>${rs.length}</strong><small>${esc(week)}</small></div><div class="stat"><span class="label">RECORDED FAILURES / ALL WEEKS</span><strong>${failures.length}</strong><small>Only committed evidence is counted</small></div><div class="stat"><span class="label">LIVE-EXECUTION GAPS</span><strong>${ready.filter(x=>x.blocking_live_execution).length}</strong><small>Independent of PoC completeness</small></div><div class="stat"><span class="label">DATA SOURCE</span><strong style="font-size:19px;letter-spacing:0">${window.projectionSource==='GitHub main'?'GitHub main':window.projectionSource==='Local preview data'?'Local preview':'Hosted fallback'}</strong><small>Research as of ${esc(data.data_as_of)}</small></div></div><div class="section-head"><h2>Inspect a recorded execution</h2><div><select id="run-picker" aria-label="Select execution">${rs.map(x=>`<option value="${esc(x.id)}" ${r?.id===x.id?'selected':''}>${esc(x.id)} · ${esc(x.status)}</option>`).join('')}</select> <button id="download-run" ${r?'':'disabled'}>Download run JSON</button></div></div><div class="surface pad">${r?`<div class="detail-grid"><div><small>RUN / TYPE</small>${esc(r.id)}<br>${esc(r.kind)}</div><div><small>START / FINISH</small>${esc(r.started_at)}<br>${esc(r.completed_at||'No completion timestamp')}</div><div><small>SOURCE REVISION</small>${r.source_revision?sourceLink('https://github.com/az2kxx/gtmtechweek/commit/'+r.source_revision,r.source_revision.slice(0,12)):'Legacy run: no revision recorded'}<br>${window.projectionSource==='GitHub main'?sourceLink('https://github.com/az2kxx/gtmtechweek/blob/main/'+(r.canonical_path||('executions/'+r.week+'/'+r.id+'.json')),'Canonical run file ↗'):'Hosted record · use Download run JSON'}</div><div><small>COST / PROVIDER CALLS</small>${r.clay_data_credits??'Unknown'} Clay DATA credits · ${r.distribution_calls??'Unknown'} distribution calls<br>${esc(r.clay_basis||'No billing evidence provided')}</div></div>${r.error?`<h3 class="error">Recorded failure</h3><p class="detail-copy error">${esc(r.error)}</p><p class="hint">Check the failed stage, its artifact and the Actions log. Fix inputs before retrying the same logical job.</p>`:''}${r.source_coverage?`<h3>Source coverage and gaps</h3><div class="rows">${r.source_coverage.map(x=>`<div class="row"><div><strong>${esc(x.source_group)}</strong><small>${esc(x.attempt_result)} ${esc(x.gap)}</small></div>${badge(x.status)}</div>`).join('')}</div>`:''}<h3>Stage evidence</h3><div class="rows">${r.stages.map(s=>`<div class="row"><div><strong>${esc(s.name)}</strong><small>${esc(s.detail)}</small>${s.error?`<p class="error">${esc(s.error)}</p>`:''}</div>${badge(s.state)}</div>`).join('')}</div>`:'<p class="empty">No execution record for this week. Select another week; no history is fabricated.</p>'}</div><div class="section-head"><div><h2>GitHub Actions status</h2><p>Checks the workflow service, including failures that prevented a run-file commit.</p></div><button id="check-actions">Check Actions now</button></div><div id="actions-result" class="surface pad">${actionsHTML()}</div><div class="section-head"><h2>Outstanding and not ready</h2><span class="hint">PoC can run without optional channels</span></div><div class="surface table-wrap"><table><thead><tr><th>COMPONENT</th><th>STATE</th><th>EVIDENCE</th><th>NEXT ACTION</th></tr></thead><tbody>${ready.map(x=>`<tr><td><strong>${esc(x.component)}</strong><small>${esc(x.priority)} · ${esc(x.owner)}</small></td><td>${badge(x.state)}</td><td style="max-width:300px">${esc(x.evidence)}</td><td style="max-width:340px">${esc(x.next_action)}</td></tr>`).join('')}</tbody></table></div><p class="hint"><a href='judges.html'>Judging guide and limitations</a> · Full continuation instructions: <a href='handover.txt' target='_blank'>Agent handover ↗</a>. Data refresh does not run scraping or send messages.</p>`}
function actionsHTML(){if(!actionsState)return '<p class="hint">Use “Check Actions now” for a live, unauthenticated status check. A green local replay does not establish that the remote workflow succeeded.</p>';if(actionsState.error)return `<p class="error">${esc(actionsState.error)}</p><p class="hint">GitHub may rate-limit anonymous requests. ${sourceLink('https://github.com/az2kxx/gtmtechweek/actions','Open Actions directly ↗')}</p>`;return `<p class="hint">Checked ${esc(actionsState.checked)}. Showing up to 5 runs.</p>${actionsState.runs.length?actionsState.runs.map(r=>`<div class="row"><div><strong>${sourceLink(r.html_url,r.name+' #'+r.run_number)}</strong><small>${esc(r.event)} · ${esc(r.created_at)} · ${esc(r.head_sha.slice(0,12))}</small></div>${badge((r.conclusion||r.status).toUpperCase())}</div>`).join(''):'<p class="hint">No GitHub Actions runs returned yet.</p>'}`}
function bindDiagnostics(){if($('#run-picker'))$('#run-picker').onchange=e=>{selectedRunId=e.target.value;render()};if($('#download-run'))$('#download-run').onclick=()=>{let r=diagnosticRun();if(!r)return;let u=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download=r.week+'-'+r.id+'.json';a.click();URL.revokeObjectURL(u)};if($('#check-actions'))$('#check-actions').onclick=async()=>{const b=$('#check-actions');b.disabled=true;b.textContent='Checking…';try{const r=await fetch('https://api.github.com/repos/az2kxx/gtmtechweek/actions/runs?per_page=5',{headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw Error('GitHub Actions status unavailable (HTTP '+r.status+').');const j=await r.json();actionsState={checked:new Date().toLocaleString(),runs:j.workflow_runs||[]}}catch(e){actionsState={error:e.message}}if(view==='diagnostics')render()}}
